pages = data['pages']

def enrich_contenu(content, new_blocks):
    marker = '<section class="content-section" id="quiz">'
    idx = content.find(marker)
    if idx == -1:
        idx = content.rfind('</section>')
    return content[:idx] + new_blocks + content[idx:]

# ===== journalisme/photojournalisme =====
k = 'journalisme/photojournalisme'
extra = (
    '<h3>Ethique et mise en scene : les limites de l\'objectivite photographique</h3>'
    '<p class="resume-text">La photographie est souvent presentee comme un enregistrement neutre du reel, mais elle est en realite le resultat de <strong>choix deliberes</strong> : le cadrage (ce qui est inclus ou exclu), l\'instant decisif (Henri Cartier-Bresson), la profondeur de champ, la lumiere, l\'angle de prise de vue. Susan Sontag (<em>Sur la photographie</em>, 1977 ; <em>Devant la douleur des autres</em>, 2003) a analyse comment la photographie peut a la fois susciter l\'empathie et creer une distance, comment l\'abondance d\'images de souffrance peut conduire a l\'anesthesie morale plutot qu\'a la mobilisation.</p>'
    '<p class="resume-text">Des scandales ont ebranle la credibilite du photojournalisme : la photo de Mussolini (dont les hommes en arriere-plan ont ete effaces), la photo du soldat albanais de Brian Walski (montage de deux photos), le debat sur la mise en scene de certaines images de conflits. World Press Photo a revise ses regles en 2015 pour exclure les retouches substantielles. La question fondamentale reste : jusqu\'ou peut-on retoucher une image d\'information tout en preservant son caractere documentaire ?</p>'
    '<div class="highlight-box"><p>Susan Sontag : photographier la souffrance d\'autrui est un acte politique et ethique. L\'abondance d\'images de violence peut finir par anesthesier plutot que mobiliser.</p></div>'
    '<h3>Les grandes agences et la mondialisation de l\'image</h3>'
    '<p class="resume-text">Le photojournalisme mondial est structure par quelques grandes <strong>agences de presse photographique</strong> : Magnum Photos (fondee en 1947 par Cartier-Bresson, Capa, Seymour et Rodger — une cooperative unique ou les photographes conservent leurs droits), Reuters Pictures, Associated Press Images, AFP Photo, Getty Images. Ces agences distribuent les images a des milliers de medias dans le monde, creant une visualite partagee : les memes photos illustrent les memes evenements sur tous les continents, avec des consequences sur la construction d\'une culture visuelle globale.</p>'
    '<p class="resume-text">Magnum Photos represente un modele unique : cooperative de photographes qui controlent leurs droits, leurs archives et leur ligne editoriale. Les membres (au nombre strict, elus par cooptation) jouissent d\'une liberte editoriale rare. Des photographes comme Sebastiao Salgado (<em>Migrations</em>, <em>Workers</em>), James Nachtwey (guerres et genocides), Dorothea Lange (Grande Depression) ont produit des oeuvres photographiques qui transcendent le reportage pour atteindre une dimension artistique et documentaire durable.</p>'
    '<div class="highlight-box"><p>Magnum Photos (1947) : une cooperative de photographes qui ont refuse de ceder leurs droits aux journaux. Un modele de resistance economique qui a permis une independance artistique et editoriale unique.</p></div>'
    '<h3>Photojournalisme de guerre et trauma</h3>'
    '<p class="resume-text">La <strong>photographie de guerre</strong> a un pouvoir unique : rendre visible ce que les mots ne peuvent transmettre. La photo de la petite fille au napalm (Nick Ut, Vietnam, 1972), l\'homme du char place Tian\'anmen (1989), la photo de l\'enfant syrien Aylan Kurdi echoue sur la plage (2015) ont eu un impact politique immediat et durable. Mais ce pouvoir pose des questions : la photo de Kevin Carter d\'un enfant affame menace par un vautour (Soudan, 1993, prix Pulitzer) a suscite une controverse mondiale sur le role du photographe — temoin ou acteur humanitaire ?</p>'
    '<p class="resume-text">Les photojournalistes qui couvrent les conflits armees sont exposes a des <strong>traumatismes psychologiques</strong> severes (PTSD, syndrome de stress post-traumatique). Dario Mitidieri, Reza Deghati et d\'autres ont temoigne de la dissociation necessaire pour photographier l\'horreur. Des organisations comme la Dart Center for Journalism and Trauma (Columbia University) offrent du soutien et forment les journalistes a prendre soin de leur sante mentale. La couverture ethique du trauma exige aussi de considerer le consentement et la dignite des personnes photographiees dans les situations de vulnerabilite extreme.</p>'
    '<div class="highlight-box"><p>Kevin Carter, auteur de la photo du vautour et de l\'enfant somalien (Pulitzer 1994), s\'est suicide trois mois apres avoir recu le prix. Son histoire illustre le trauma des photojournalistes de guerre et la question morale du temoignage face a la souffrance.</p></div>'
)
